/* Cloaked Pay — shared media. Loaded before the app so every page uses the
   same video, cover art, logos and card faces instead of duplicating them.
   Top-level const in a classic script is visible to the scripts that follow. */
const COVER = "data:image/webp;base64,";
/* The same eight cards, turned: bkgd-2, paper flood-filled to transparent from
   the borders inward, rotated 20 degrees counter-clockwise, then trimmed to
   1312x1030. The rotation is what makes it usable — bkgd-2's fan descends at 62
   degrees, far too steep for a cover, and turning it left brings the axis to 42
   and the artwork from 414x634 on screen to 639x501, so it bleeds sideways like
   the vertical cover instead of running off the bottom of the frame.
   Premultiplied before rotating: otherwise the transparent paper's RGB bleeds
   into the card edges as a pale fringe. */
const COVER_H = "data:image/webp;base64,";


